import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {chromium,webkit} from 'playwright';
import {chapterHash} from '../lib/practice-chapters.ts';
import {collectionProgressId,roundProgressPrefix} from '../lib/round-progress.ts';
const root='docs/klink10-speaking-20261102',m=JSON.parse(readFileSync(root+'/manifest.json')),es=JSON.parse(readFileSync('public'+m.row.url)).exercises,base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:19041',out=process.env.KLINK_TEST_OUTPUT||root+'/local';mkdirSync(out+'/screens',{recursive:true});const checks=[],errors=[],key=roundProgressPrefix+collectionProgressId('sentence-speak',m.row.id,m.row.url);
for(const[engine,type]of Object.entries({chromium,webkit})){
 const browser=await type.launch({headless:true,...(engine==='chromium'?{channel:'chrome'}:{})});
 try{for(const width of [390,1280]){const context=await browser.newContext({viewport:{width,height:844},colorScheme:width===390?'dark':'light'});await context.addInitScript(()=>{const NativeAudio=window.Audio;window.endedSources=[];window.Audio=class extends NativeAudio{constructor(...args){super(...args);this.addEventListener('ended',()=>window.endedSources.push(this.currentSrc));}};});const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto(base);await page.evaluate(()=>localStorage.setItem('k10-existing-draft','Mijn bestaande antwoord'));await page.goto(base+'/'+chapterHash({chapter:'speaking',activity:'sentence-speak',collection:m.row.id,level:'alfa-a',help:'guided'}));
 for(const[i,e]of es.entries()){const task=page.locator(`[data-exercise-id="${e.exerciseId}"]`);await task.waitFor();assert(await task.locator('[data-practice-next]').isDisabled());await task.getByRole('button',{name:'Klaar',exact:true}).click();assert.equal(await task.locator('.cp-exercise-feedback.right').count(),0);await page.evaluate(()=>{window.endedSources=[];});
 await task.getByRole('button',{name:'Luister naar '+e.displayWord,exact:true}).first().click();await page.waitForFunction(src=>window.endedSources.some(s=>s.endsWith(src)),e.prompt.audio.src);await task.getByRole('button',{name:'Klaar',exact:true}).click();await task.locator('.cp-exercise-feedback.right').waitFor();assert((await task.locator('.cp-exercise-feedback').innerText()).includes('Luister zelf of samen met je docent'));await task.locator('[data-practice-next]:not(:disabled)').waitFor();
 if(i===0)await page.screenshot({path:`${out}/screens/${engine}-${width}.png`,fullPage:true});await task.locator('[data-practice-next]').click();await page.waitForFunction(({key,id})=>JSON.parse(localStorage.getItem(key)).done.includes(id),{key,id:e.exerciseId});if(i===0){await page.reload();await page.locator(`[data-exercise-id="${es[1].exerciseId}"]`).waitFor();}checks.push({engine,width,id:e.exerciseId,listenBeforeCompletion:true,participationOnly:true,manualAdvance:true});}
 assert.equal(await page.evaluate(()=>localStorage.getItem('k10-existing-draft')),'Mijn bestaande antwoord');assert.equal((await page.evaluate(k=>JSON.parse(localStorage.getItem(k)).done,key)).length,10);await context.close();}}finally{await browser.close();}}
assert.equal(checks.length,40);assert.deepEqual(errors,[]);writeFileSync(out+'/browser.json',JSON.stringify({base,checks,errors,completedProgressAndResumePreserved:true,existingDraftPreserved:true,audioMocked:false},null,2)+'\n');console.log('PASS 40 guided speech flows, progress, reload and existing draft.');
